import React, { FC } from "react";

import css from "./style.module.css";
import clsx from "clsx";

interface Props {
  value: string | number;
  className?: string;
}

export const Level: FC<Props> = ({ value, className }) => {
  return (
    <button className={clsx(css.level, className)}>
      <svg
        width="256"
        height="256"
        viewBox="0 0 256 256"
        fill="none"
        xmlns="http://www.w3.org/2000/svg">
        <path
          d="M128 240C189.856 240 240 189.856 240 128C240 66.1441 189.856 16 128 16C66.1441 16 16 66.1441 16 128C16 189.856 66.1441 240 128 240Z"
          stroke="currentColor"
          stroke-width="16"
          stroke-linecap="round"
          stroke-linejoin="round"
        />
      </svg>
      <span className={css.levelValue}>{value}</span>
    </button>
  );
};
